### Query.php

```
<?php    
use PDO;

class Query
{
/*
PDO对象
*/
    protected $pdo;

/*
查询表名
*/
    protected $table;

/*
查询字段
*/
    protected $field = '*';

/*
where and条件
*/
    protected $where = [];

/*
where or条件
*/
    protected $whereOr = [];

/*
排序字段
*/
    protected $order = 'id';

/*
限制查询数
*/
    protected $limit;

/*
实例化时存入PDO对象
*/
    public function __construct($pdo)
    {
        $this->pdo = $pdo;
        return $this;
    }

/*
设置表名
*/
    public function table($table)
    {
        $this->table = $table;
        return $this;
    }

/*
设置请求字段
*/
    public function field($field)
    {
        if(strpos($field, ',')){
            $field = explode(',', $field);
            $field_tmp = null;
            foreach($field as $k=>$row){
                if($k > 0){
                    $field_tmp = $field_tmp .',`'. $row .'`';
                }else{
                    $field_tmp = $field_tmp .'`'. $row .'`';
                }
            }
            $field = $field_tmp;
        }
        $this->field = $field;
        return $this;
    }

/*
设置where条件
*/
    public function where($key, $op, $value = null)
    {
        if($value === null){
            $value = $op;
            $op = '=';
        }
        $this->where[] = [
            'key' => $key,
            'op' => $op,
            'value' => $value
        ];
        return $this;
    }

/*
设置where下的or条件
*/
    public function whereOr($key, $op, $value = null)
    {
        if($value === null){
            $value = $op;
            $op = '=';
        }
        $this->whereOr[] = [
            'key' => $key,
            'op' => $op,
            'value' => $value
        ];
        return $this;
    }

/*
生成where条件的SQL语句与数据数组
*/
    protected function whereBuilder()
    {
        $sql = null; $data = [];
        if($this->where){
            foreach($this->where as $k=>$row){
                if($k > 0){
                    $sql = $sql . 'AND `'. $row['key'] .'` '. $row['op'] . ' ';
                }else{
                    $sql = $sql . 'WHERE `'. $row['key'] .'` '. $row['op'] . ' ';
                }
                if($row['op'] === 'in'){
                    $sql = $sql . '(';
                    foreach($row['value'] as $r_k=>$r_v){
                        if($r_k > 0){
                            $sql = $sql . ',?';
                        }else{
                            $sql = $sql . '?';
                        }
                        $data[] = $r_v;
                    }
                    $sql = $sql . ') ';
                }else{
                    $sql = $sql . '? ';
                    $data[] = $row['value'];
                }
            }
        }
        if($this->whereOr){
            foreach($this->whereOr as $row){
                $sql = $sql . 'OR `'. $row['key'] .'` '. $row['op'] . ' ';
                if($row['op'] === 'in'){
                    $sql = $sql . '(';
                    foreach($row['value'] as $r_k=>$r_v){
                        if($r_k > 0){
                            $sql = $sql . ',?';
                        }else{
                            $sql = $sql . '?';
                        }
                        $data[] = $r_v;
                    }
                    $sql = $sql . ') ';
                }else{
                    $sql = $sql . '? ';
                    $data[] = $row['value'];
                }
            }
        }
        return [
            'sql' => $sql,
            'data' => $data
        ];
    }

/*
设置排序字段
*/
    public function order($order)
    {
        $this->order = $order;
        return $this;
    }

/*
设置限制查询数
*/
    public function limit($num)
    {
        $this->limit = $num;
        return $this;
    }

/*
查询特定字段
*/
    public function value($field)
    {
        $param = $this->whereBuilder();
        $sql = 'SELECT `'. $field . '` FROM `'. $this->table .'` '. $param['sql'] .'LIMIT 1;';
        $obj = $this->pdo->prepare($sql);
        if(!$obj) return Db::error();
        $res = $obj->execute($param['data']);
        $list = $obj->fetchAll(PDO::FETCH_ASSOC);
        if(isset($list[0][$field])){
            return $list[0][$field];
        }else{
            return false;
        }
    }

/*
查询一条记录
*/
    public function find()
    {
        $param = $this->whereBuilder();
        $sql = 'SELECT '. $this->field . ' FROM `'. $this->table .'` '. $param['sql'] .'LIMIT 1;';
        $obj = $this->pdo->prepare($sql);
        if(!$obj) return Db::error();
        $res = $obj->execute($param['data']);
        $data = $obj->fetchAll(PDO::FETCH_ASSOC);
        if(isset($data[0])){
            return $data[0];
        }else{
            return false;
        }
    }

/*
查询列表
*/
    public function select()
    {
        $param = $this->whereBuilder();
        $sql = 'SELECT '. $this->field . ' FROM `'. $this->table .'` '. $param['sql'] .' ';
        $sql .= 'ORDER BY '. $this->order . ' ';
        if($this->limit) $sql .= 'LIMIT '. $this->limit .';';
        $obj = $this->pdo->prepare($sql);
        if(!$obj) return Db::error();
        $res = $obj->execute($param['data']);
        $list = $obj->fetchAll(PDO::FETCH_ASSOC);
        return $list;
    }

/*
按页查询
*/
    public function page($num, $key = 'page')
    {
        if(input('?'.$key)){
            if(is_numeric(input($key))){
                $page = intval(input($key));
            }else{
                $page = 1;
            }
        }else{
            $page = 1;
        }
        $param = $this->whereBuilder();
        $sql = 'SELECT '. $this->field . ' FROM `'. $this->table .'` '. $param['sql'] .' ';
        $sql .= 'ORDER BY '. $this->order . ' ';
        $sql .= 'LIMIT '. ($num * ($page - 1)) .','. $num .' ';
        $sql .= ';';
        $obj = $this->pdo->prepare($sql);
        if(!$obj) return Db::error();
        $res = $obj->execute($param['data']);
        $list = $obj->fetchAll(PDO::FETCH_ASSOC);

        $count = $this->count('id');

        $url = $_SERVER["REQUEST_URI"];
        if(strpos($url, '?')) $url = substr($url, 0, strpos($url, '?'));
        if(count($_GET) > 0){
            $i = 0;
            foreach($_GET as $get_k=>$get_v){
                if($get_k !== $key){
                    if($i > 0){
                        $url .= '&'. $get_k .'='. $get_v;
                    }else{
                        $url .= '?'. $get_k .'='. $get_v;
                        $i++;
                    }
                }
            }
            if($i > 0){
                $url .= '&page=';
            }else{
                $url .= '?page=';
            }
        }else{
            $url .= '?page=';
        }

        return [
            'data' => $list,
            'url' => $url,
            'limit' => $num,
            'page' => $page,
            'count' => $count
        ];
    }

/*
插入一条记录
*/
    public function insert($data)
    {
